import{_ as o,o as r,c as n,ag as s}from"./chunks/framework.KxDd3USm.js";const A=JSON.parse('{"title":"10.6 答案与解析","description":"","frontmatter":{},"headers":[],"relativePath":"10-标准化与知识产权/99-答案与解析.md","filePath":"10-标准化与知识产权/99-答案与解析.md"}'),g={name:"10-标准化与知识产权/99-答案与解析.md"};function p(a,t,u,q,e,B){return r(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="_10-6-答案与解析" tabindex="-1">10.6 答案与解析 <a class="header-anchor" href="#_10-6-答案与解析" aria-label="Permalink to &quot;10.6 答案与解析&quot;">​</a></h1><h3 id="课后考题答案" tabindex="-1">课后考题答案 <a class="header-anchor" href="#课后考题答案" aria-label="Permalink to &quot;课后考题答案&quot;">​</a></h3><p><strong>1. A</strong> 著作权（含软件著作权）实行<strong>自动保护原则</strong>，自<strong>开发（创作）完成之日</strong>起自动产生。登记（B）、发表（C）都不是取得前提，软件著作权也无需审批（D）。易错点：登记证书只是<strong>证据</strong>，不是权利来源。</p><p><strong>2. C</strong> 署名权属于人身权，<strong>永久保护</strong>。A 发表权有期限（终生 + 死后 50 年）——这是最常见的陷阱，别把发表权也当成永久；B、D 是财产权，均有期限。口诀「署改完永久」：署名权、修改权、保护作品完整权三样永久。</p><p><strong>3. A</strong> 公民作品的财产权保护期为<strong>作者终生 + 死后 50 年</strong>，截止于死后<strong>第 50 年的 12 月 31 日</strong>（&quot;12 月 31 日&quot;是法定截止日，B 的 1 月 1 日是干扰写法）。C 是法人作品的算法，D 是人身权的待遇，财产权没有永久保护。</p><p><strong>4. B</strong> 本题问的是<strong>软件</strong>（法人软件）——按软件保护条例，法人软件著作权的保护期为 <strong>50 年，截止于首次发表后第 50 年的 12 月 31 日</strong>；开发完成之日起 50 年内未发表的，法律不再保护。A 是&quot;自开发完成算&quot;的干扰；C 错（保护有期限）、D 年限错（25 年）。</p><p><strong>边界提醒（别记串）</strong>：软件是特例——条例对法人软件统一按&quot;首次发表后 50 年&quot;。若是<strong>一般作品</strong>（非软件）的法人作品，则分两条线：<strong>发表权</strong>锚&quot;创作完成后 50 年&quot;，<strong>财产权</strong>锚&quot;首次发表后 50 年&quot;。</p><p><strong>5. B</strong> 属于职务开发：任职期间<strong>针对本单位明确指定的开发目标</strong>所开发的软件，著作权归<strong>单位</strong>享有（《计算机软件保护条例》的职务开发规则）。C 共同享有是合作开发的规则，与职务开发无关；&quot;明确指定开发目标&quot;在题面已写明，归属确定，D 不成立。对照第一节表格：软件属于&quot;特殊职务作品&quot;，作者只留署名权。</p><p><strong>6. B</strong> 委托开发，合同约定优先；<strong>合同未明确约定的，著作权归受托人（实际开发的乙公司）</strong>。这是第一节&quot;委托作品&quot;行的原规则，判断句：「没说好的归干活的」。A 是&quot;我出钱就该归我&quot;的想当然错误。</p><p><strong>7. A</strong> 专利实行<strong>先申请原则</strong>：同样发明创造，专利权授予<strong>最先申请</strong>的人，丙公司早 3 天，独得授权。C 错，专利只授一家，不存在共有；D 错，&quot;协商&quot;只在<strong>同日申请</strong>时适用，丙丁相差 3 天，无需协商。</p><p><strong>8. B</strong> 现行《专利法》（2021 年 6 月 1 日施行）规定外观设计保护期为<strong>15 年</strong>，自申请日起算。C 的 10 年是 2021 年修法前的旧标准，旧资料若出现该数字须按新法纠正；A 是发明专利的年限。</p><p><strong>9. B</strong> 职务发明：<strong>执行本单位的任务</strong>所完成的发明创造，专利申请权归<strong>单位</strong>；批准后单位为专利权人。A 的&quot;业余时间&quot;是经典陷阱——只要属于执行本单位任务（承担所里课题），即使业余时间做，也是职务发明；&quot;归国家&quot;（D）无此规则。</p><p><strong>10. C</strong> 化工产品的<strong>合成工艺方法</strong>是技术方案，具备三性即可授予专利。A 疾病的诊断和治疗方法、B 智力活动的规则和方法、D 动物和植物品种，都是<strong>不授予</strong>专利权的法定对象（注意 D 的陷阱延伸：动物品种本身不授予，但其<strong>生产方法</strong>可以授予）。</p><p><strong>11. B</strong> 注册商标有效期 <strong>10 年</strong>，自核准注册之日起算；期满前 12 个月内可办续展（另加 6 个月宽展期），每次续展 10 年，<strong>次数不限</strong>——商标可以无限续命，与专利&quot;到期即死&quot;形成对比。</p><p><strong>12. C</strong> 现行法律法规下必须使用注册商标的商品只有<strong>烟草制品</strong>（卷烟、雪茄烟和有包装的烟丝）。A 人用药品曾属强制注册范围，现已不再强制，是老题库残留干扰项。</p><p><strong>13. B</strong> 拆代号：<strong>SJ</strong> 是电子工业行业标准代号，<strong>/T</strong> 表示推荐性 → 推荐性行业标准。A 错，GB 才是国家标准；C 的地方标准代号是 DB；D 的企业标准代号是 Q/。</p><p><strong>14. B</strong> ISO 是国际标准化组织，ISO 9001 属<strong>国际标准</strong>。A 的 GB/T 是我国推荐性国家标准（我国等同采用 ISO 9001 形成的本国标准，代号已变）；C 的 DB11/T 是北京市推荐性地方标准；D 的 Q/ 是企业标准。国际标准由 ISO、IEC、ITU 等制定。</p><p><strong>15. D</strong> 合法复制品所有人<strong>为防复制品损坏制作备份</strong>是条例明确赋予的权利（备份只能自留）。A 备份<strong>提供给他人</strong>使用——侵权；B 出租营利——未经许可出租软件是侵权行为；C 丧失原件所有权后备份<strong>必须销毁</strong>，继续保留即侵权。</p><p><strong>16.（场景判定题）</strong> (1) 著作权归<strong>甲公司</strong>。小吴是&quot;在职期间、按公司指派、使用公司设备和资料、完成公司指派任务&quot;的职务开发，按《计算机软件保护条例》职务开发规则，著作权归单位，小吴只保留署名权。 (2) <strong>均侵权</strong>。著作权归甲公司，小吴以个人名义登记他人的软件，属于&quot;将他人的软件作为自己的软件登记/发表&quot;，构成侵权；其授权乙公司有偿使用属于未经著作权人许可的发行/许可行为，乙公司未获甲公司许可，同样构成侵权。 (3) <strong>丙大学不侵权，丁公司侵权</strong>。丙大学为课堂教学目的、少量复制、未提供他人、非商业目的，属于合理使用的免责情形；丁公司未经许可在网站上向公众提供软件下载，侵犯信息网络传播权（发布），无任何免责事由。</p><h3 id="精华题答案" tabindex="-1">精华题答案 <a class="header-anchor" href="#精华题答案" aria-label="Permalink to &quot;精华题答案&quot;">​</a></h3><p><strong>1. A</strong> 《中华人民共和国著作权法》和《计算机软件保护条例》共同构成我国保护计算机软件著作权的基本法律框架。注意干扰项：我国<strong>没有</strong>单独的&quot;《软件法》&quot;，B 的《专利法》保护的是技术方案而非代码作品。</p><p><strong>2. C</strong> 国际上保护计算机软件知识产权的主要方式是实施<strong>版权法（著作权法）</strong>——软件在全球范围内都作为&quot;文字作品&quot;纳入版权保护，这是国际通行做法。专利、合同、刑法只是辅助手段。</p><p><strong>3. B</strong> 商业秘密无固定保护期，<strong>保密措施有效就持续受保护</strong>；他人<strong>独立研发</strong>出同样的秘密不构成侵权（商业秘密只对抗&quot;不正当获取&quot;，不对抗正当获得）。A、C 的固定年限是拿专利/商标的保护期来张冠李戴；D 错，商业秘密正是受《反不正当竞争法》等保护的。</p><p><strong>4. B</strong> 软件著作权<strong>自开发完成之日起自动产生</strong>，登记不是取得前提（自愿登记），登记证书只是打官司时的<strong>初步证明</strong>。A、C、D 都把&quot;登记&quot;当成了权利来源，方向性错误。</p><p><strong>5. B</strong> 发表权保护期为<strong>作者终生及其死亡后 50 年</strong>。A 错——永久保护的是署名权、修改权、保护作品完整权，发表权不在其中（人死后总不能永远替作者决定发不发表）。</p><p><strong>6. B</strong> 标准复审周期一般不超过 <strong>5 年</strong>。这是标准化常识题，数字只能背。</p><p><strong>7. B</strong> 为<strong>兼容性需要</strong>、且通过正当途径<strong>无法获得必要的接口信息</strong>时的反编译，属于软件保护条例明确允许的例外，不构成侵权。A 错在&quot;一律&quot;——条例设有例外条款；C 与专利无关；D 错，软件享有著作权。</p><p><strong>8. B</strong><strong>GB</strong>（不带 T）才是强制性国家标准，GB 18030 是强制性字符编码标准。A 的 GB/T 是推荐性、C 的 GB/Z 是指导性技术文件、D 的 SJ/T 是电子行业推荐性标准。判断口诀：<strong>带 T（推荐）、带 Z（指导）都不是强制，GB 光杆才是强制</strong>。</p><h3 id="补充题答案" tabindex="-1">补充题答案 <a class="header-anchor" href="#补充题答案" aria-label="Permalink to &quot;补充题答案&quot;">​</a></h3><p><strong>1. B</strong> 著作权<strong>自动产生</strong>（创作完成即享有，无需登记注册）；专利权须申请授权、商标权须注册取得，都非自动取得；商业秘密<strong>不登记不申请</strong>，靠保密措施维持。A 错——著作权无需登记；C 错——商业秘密不靠申请登记；D 错——商业秘密无&quot;先申请原则&quot;。</p><p><strong>2. B</strong> 电路板产品<strong>上市即可被逆向</strong>，商业秘密&quot;捂着守不住&quot;，A 不可行；要获得&quot;防他人独立实施&quot;的最强独占，只能走 <strong>专利公开换独占</strong>（哪怕别人独立想到也侵权，见四权对比表&quot;独立研发是否侵权&quot;一行）。C 商标只管品牌标识、管不住技术方案；D 放弃保护不可取。</p><p><strong>3. B</strong><strong>T/ + 团体代号</strong>是团体标准（T 孤悬在首、后接团体代号）。A 错——推荐性国家标准代号是 GB/T，T 在 GB 之后；C 错——企业标准代号是 Q/；D 错——团体标准属自愿采用的推荐层级，非强制性必须执行。</p><p><strong>4. B</strong><strong>GB/T</strong> 中 T 在 GB 之后，表示<strong>推荐性国家标准</strong>。A 错——带 T 即非强制，强制性国家标准是 GB（不带 T）；C 团体标准是 T/ 打头；D 行业标准用各行业代号（如 SJ、YD、DL）。判别句：<strong>T 在后是&quot;推荐&quot;，T 在前是&quot;团体&quot;</strong>。</p><p><strong>5. D</strong> 只有<strong>商业秘密</strong>允许他人独立研发或反向工程获得同样信息而不侵权——它只对抗不正当获取，不对抗正当获得。著作权只要表达相同即构成侵权（A）；专利权是独占权，独立想到也侵权（B）；商标权下近似标识不得注册使用（C）。对应四权对比表的第五行。</p><p><strong>6. B</strong> 商标权<strong>自核准注册之日起算 10 年</strong>，期满前 12 个月（另有 6 个月宽展期）可办续展，每次续展 10 年、<strong>次数不限</strong>。A 错——起算是核准注册日，不是申请日（对比专利自申请日起算）；C 错——不是首次使用之日；D 错——续展次数不限，不是 3 次。</p><hr><p><strong>下一课</strong>：学完本课、做完题后，对我说「下一课」，我将生成 <a href="/ruankao/09-计算机系统基础/">09-计算机系统基础.md</a> 并更新进度表（若你已先学了 09，也可以直接指定要 11 专业英语）。</p>',37)])])}const D=o(g,[["render",p]]);export{A as __pageData,D as default};
